using NUnit.Framework;

[TestFixture]
public class CountVowelsTests
{
    [TestCase("Anna", 2)]
    [TestCase("Michael", 3)]
    [TestCase("Rhythm", 0)]
    public void Counts_Vowels_Correctly(string name, int expected)
    {
        Assert.That(CountVowels(name), Is.EqualTo(expected));
    }

    private int CountVowels(string name)
    {
        int count = 0;

        foreach (var ch in name)
        {
            char lower = char.ToLowerInvariant(ch);

            if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u')
                count++;
        }

        return count;
    }
}
